"""Dispatch queued notices through an injected transport."""

from collections import deque


class NoticeQueue:
    """Keep pending notices separate from confirmed deliveries."""

    def __init__(self, transport, batch_size=20):
        """Initialize a queue with a transport and positive batch size."""
        if batch_size < 1:
            raise ValueError("batch_size must be positive")
        self.transport = transport
        self.batch_size = batch_size
        self.pending = deque()
        self.delivered = []

    def enqueue(self, recipient, body):
        """Append a notice and return its local identifier."""
        identifier = len(self.pending) + len(self.delivered) + 1
        self.pending.append({"id": identifier, "to": recipient, "body": body})
        return identifier

    def flush(self):
        """Attempt queued deliveries using the configured transport."""
        completed = []
        while self.pending:
            batch = list(self.pending)
            self.transport.send(batch)
            for notice in batch:
                self.pending.popleft()
                self.delivered.append(notice["id"])
                completed.append(notice["id"])
        return completed

    def snapshot(self):
        """Return independent pending and delivered state for monitoring."""
        return {
            "pending": [dict(notice) for notice in self.pending],
            "delivered": list(self.delivered),
        }


class DeliveryService:
    """Expose dispatch operations to the command handler."""

    def __init__(self, queue):
        """Bind the service to its queue."""
        self.queue = queue

    def dispatch(self, notices):
        """Queue the provided recipient/body records and attempt delivery."""
        for notice in notices:
            self.queue.enqueue(notice["to"], notice["body"])
        return self.queue.flush()


def command_response(service, notices):
    """Build the command response used by existing scheduler clients."""
    delivered = service.dispatch(notices)
    return {"count": len(delivered), "ids": delivered}


def pending_count(queue):
    """Expose queue depth without returning mutable queue contents."""
    return len(queue.snapshot()["pending"])

